import requests

# Attempt to fetch the USD to PHP rate from the specified public endpoint
def get_exchange_rate():
    url = 'https://exchangerate-api.com/api/latest/USD'  # This is a placeholder, actual public API may vary
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raise an error for bad responses
        data = response.json()  # Parse response as JSON
        return data['rates']['PHP']  # Extract PHP rate from the response
    except Exception as e:
        return str(e)

exchange_rate = get_exchange_rate()  # Fetch the exchange rate
